THEME = ("T07", "Politiques organisationnelles (OrBAC)")
SOURCE = "Abou El Kalam et al., « Organization Based Access Control », IEEE POLICY, 2003 ; Cuppens et Miège, « Modelling contexts in the Or-BAC model », ACSAC, 2003 ⚠ à vérifier"
Q = [
(1,"Que signifie OrBAC ?","Organization-Based Access Control","Object-Role Based Access Control","Open Rule Based Access Check","Online Resource Business Access Control",
 "OrBAC (2003) place l'organisation au centre de la politique d'accès."),
(1,"Quelle idée centrale distingue OrBAC de RBAC ?","La politique est exprimée au niveau abstrait d'une organisation avec ses contextes","Les rôles n'existent pas","Les mots de passe sont obligatoires","Tout est discrétionnaire",
 "OrBAC permet de définir la même politique pour plusieurs organisations, avec des règles spécifiques au contexte."),
(2,"Dans OrBAC, que désigne un « rôle » ?","Un groupe abstrait de sujets qui jouent la même fonction dans l'organisation","Un fichier","Un mot de passe","Un journal",
 "Comme en RBAC, un rôle regroupe des sujets, mais il est défini par organisation."),
(2,"Dans OrBAC, que désigne une « vue » ?","Un groupe abstrait d'objets partageant des propriétés","Une page web","Un écran d'administration","Un utilisateur",
 "La vue est à l'objet ce que le rôle est au sujet : par exemple « dossier client »."),
(2,"Dans OrBAC, que désigne une « activité » ?","Un groupe abstrait d'actions, comme consulter ou modifier","Une réunion","Une tâche de sauvegarde","Un rôle",
 "Par exemple, « consulter » regroupe lire, afficher, imprimer."),
(2,"Quels éléments composent une permission OrBAC ?","Organisation, rôle, activité, vue, contexte","Sujet, niveau, catégorie","Utilisateur, mot de passe, session","Attribut, algorithme, clé",
 "Permission(Org, Rôle, Activité, Vue, Contexte)."),
(2,"Pourquoi OrBAC distingue-t-il niveau abstrait et niveau concret ?","Pour séparer la politique générale de ses applications aux sujets, objets et actions réels","Pour chiffrer les règles","Pour accélérer le réseau","Pour supprimer l'organisation",
 "La politique abstraite est écrite une fois ; des relations l'appliquent aux entités concrètes."),
(2,"Quelle relation OrBAC associe un sujet à un rôle dans une organisation ?","Empower","Use","Consider","Define",
 "Empower(Organisation, Sujet, Rôle) : le sujet reçoit le rôle."),
(2,"Quelle relation OrBAC associe un objet à une vue ?","Use","Empower","Consider","Grant",
 "Use(Organisation, Objet, Vue)."),
(2,"Quelle relation OrBAC associe une action à une activité ?","Consider","Empower","Use","Revoke",
 "Consider(Organisation, Action, Activité)."),
(2,"Quel intérêt a la notion de contexte dans OrBAC ?","La permission s'applique seulement si le contexte est vérifié","Elle supprime les rôles","Elle chiffre les objets","Elle remplace les utilisateurs",
 "Le contexte peut être temporel, spatial, lié à un prérequis ou à une déclaration de l'utilisateur."),
(2,"Quel est un exemple de contexte temporel OrBAC ?","En heures ouvrées","Dans la salle B","Si l'utilisateur est médecin","Si le fichier est PDF",
 "Le contexte temporel dépend de la date ou de l'heure."),
(2,"Quel est un exemple de contexte spatial OrBAC ?","Depuis le site de l'agence","Le lundi matin","Avec un mot de passe long","Si le fichier est lourd",
 "Le contexte spatial dépend de l'emplacement du sujet ou de l'objet."),
(3,"Quel est un exemple de contexte « prérequis » ?","Le dossier est à l'état « validé »","Le sujet est dans un bâtiment","Il est midi","Le fichier est petit",
 "Un prérequis dépend de l'état du système ou des données."),
(3,"Quel est un exemple de contexte « déclaré par l'utilisateur » ?","L'utilisateur déclare une urgence médicale","L'heure est 14 h","Le fichier est classé","L'IP est interne",
 "Le sujet affirme une situation qui active le contexte, avec traçabilité a posteriori."),
(2,"Quelle règle OrBAC est une interdiction ?","Prohibition(Épinal, Stagiaire, Modifier, Comptes, Défaut)","Permission(Épinal, Comptable, Consulter, Comptes, Heures ouvrées)","Obligation(Épinal, Gestionnaire, Archiver, Dossiers, Fin de mois)","Recommandation(Épinal, Chef, Relire, Notes, Défaut)",
 "OrBAC exprime aussi des interdictions, des obligations et des recommandations."),
(2,"Quel avantage OrBAC présente-t-il pour une entreprise multi-sites ?","On définit la politique par organisation, avec des particularités locales","On supprime les sites","On utilise un seul mot de passe","On interdit les rôles",
 "La même structure de politique s'applique à chaque agence, avec des contextes ou des règles propres."),
(3,"Quelle règle OrBAC est difficile à exprimer avec un RBAC de base ?","Un gestionnaire peut modifier un dossier seulement dans son agence et pendant les heures ouvrées","Un comptable peut lire les comptes","Un administrateur peut gérer les utilisateurs","Un utilisateur peut se connecter",
 "Elle combine organisation (agence) et contexte (heure), absents du RBAC standard."),
(2,"Qu'est-ce qu'une hiérarchie d'organisations en OrBAC ?","Une organisation peut hériter des règles d'une organisation parente","Un classement de salaires","Un arbre de fichiers","Une liste d'utilisateurs",
 "La politique d'une filiale peut hériter du groupe et ajouter des spécialisations."),
(3,"Pourquoi OrBAC convient-il aux systèmes de santé ?","Il exprime des règles liées au contexte (urgence, service, relation de soin)","Il supprime le secret médical","Il remplace les dossiers","Il n'a pas de journaux",
 "Les contextes d'urgence et de service sont essentiels dans les établissements de santé."),
(2,"Quelle différence essentielle entre OrBAC et XACML ?","OrBAC est un modèle de politique, XACML un langage et une architecture d'évaluation","Ils sont identiques","OrBAC est un protocole réseau","XACML est un modèle de rôles",
 "On peut implémenter une politique OrBAC avec un moteur de type XACML."),
(1,"À quoi sert une politique de sécurité écrite ?","À donner un cadre commun et vérifiable aux règles de contrôle d'accès","À remplacer les mots de passe","À supprimer les audits","À réduire le réseau",
 "Elle fixe les principes et les responsabilités qui seront déclinés techniquement."),
(2,"Qui doit approuver une politique de contrôle d'accès dans une organisation ?","La direction, sur proposition de la sécurité et des métiers","Un stagiaire seul","Le fournisseur","Un utilisateur choisi au hasard",
 "L'engagement de la direction donne l'autorité et les moyens."),
(2,"Qu'est-ce qu'une règle d'obligation en politique de sécurité ?","Une action à accomplir dans certaines conditions, comme journaliser un accès d'urgence","Une interdiction totale","Un droit de lecture","Un chiffrement",
 "Les obligations accompagnent les permissions pour garantir la traçabilité."),
(2,"Qu'est-ce qu'une recommandation en OrBAC ?","Une règle souhaitable mais non strictement imposée","Une règle d'interdiction stricte","Un mot de passe","Une sauvegarde",
 "Elle exprime une préférence : par exemple signer les courriels sensibles."),
(3,"Quelle règle OrBAC peut exprimer un conflit entre permission et interdiction ?","Plusieurs règles s'appliquant à la même situation avec des priorités","Une seule règle","Un journal","Une sauvegarde",
 "Il faut une stratégie de résolution des conflits, par exemple priorité à l'interdiction."),
(2,"Comment éviter les conflits entre règles d'une politique complexe ?","Définir des priorités et tester la politique avec des cas","Ignorer les règles","Supprimer les interdictions","Multiplier les exceptions sans documentation",
 "La détection de conflits fait partie de la gouvernance de la politique."),
(2,"Pourquoi définir des activités abstraites plutôt que de lister chaque action ?","Pour garder une politique courte et stable quand les applications changent","Pour réduire les mots de passe","Pour supprimer les objets","Pour augmenter les droits",
 "Une activité regroupe plusieurs actions techniques qui évoluent."),
(2,"Quelle règle illustre bien un contexte « urgence » ?","Un médecin peut consulter le dossier d'un patient hors de son service en cas d'urgence déclarée, avec journalisation","Tout employé peut tout lire","Seul le propriétaire accède","Personne n'accède jamais",
 "Le contexte autorise un accès exceptionnel encadré par une obligation de traçabilité."),
(3,"Quel risque présente un contexte « déclaré par l'utilisateur » ?","L'abus : il peut déclarer une urgence qui n'existe pas","Il est trop lent","Il supprime les rôles","Il chiffre le journal",
 "Il faut des contrôles a posteriori et des sanctions."),
(2,"Quel intérêt a un tableau de correspondance entre rôles, vues et activités ?","Relire et valider la politique avec les métiers","Supprimer l'audit","Cacher la politique","Chiffrer les rôles",
 "Il rend la politique lisible par des non-informaticiens."),
(2,"Dans quel cas un modèle organisationnel est-il particulièrement utile ?","Plusieurs entités (agences, filiales) doivent appliquer des règles proches mais pas identiques","Un seul poste isolé","Un fichier unique","Un serveur sans utilisateurs",
 "Il évite de dupliquer des politiques entières."),
(1,"Quel est l'intérêt de documenter la politique d'accès ?","Pouvoir la relire, la faire évoluer et la démontrer en audit","Augmenter le nombre de documents","Supprimer les contrôles","Cacher les règles",
 "Une politique non documentée ne peut ni être appliquée de façon cohérente ni être auditée."),
(2,"Qu'appelle-t-on « délégation » de droits en organisation ?","Un transfert temporaire d'un droit à une autre personne, tracé et borné","Un partage de mot de passe","Une suppression","Un chiffrement",
 "Elle doit préciser durée, périmètre et responsabilité."),
(3,"Pourquoi la délégation par partage de mot de passe est-elle à proscrire ?","Elle supprime l'imputabilité et élargit les droits sans contrôle","Elle est trop rapide","Elle chiffre les données","Elle supprime les rôles",
 "Il faut une délégation formelle plutôt qu'un partage d'identifiants."),
(2,"Quelle donnée est la plus utile pour vérifier une règle d'agence ?","L'attribut d'agence rattachée à l'utilisateur et à la ressource","La couleur du dossier","La date de création du compte seulement","Le nom du serveur",
 "La comparaison des deux attributs exprime la règle « même agence »."),
(2,"Une politique dit : « Toute modification des comptes exige l'approbation d'un second responsable ». De quel type de règle s'agit-il ?","Une obligation liée à la séparation des tâches","Une permission de lecture","Une prohibition de connexion","Une recommandation d'archivage",
 "Elle impose une condition de validation par une deuxième personne."),
(3,"Quelle erreur de conception rend une politique OrBAC fragile ?","Écrire des règles directement sur des sujets et objets individuels","Utiliser des rôles","Utiliser des contextes","Utiliser des organisations",
 "On perd l'avantage de l'abstraction : la politique devient lourde à maintenir."),
(2,"Quelle règle est la plus conforme au moindre privilège ?","Permission(Metz, Magasinier, Consulter, Stocks, Heures ouvrées)","Permission(Metz, Magasinier, Tout faire, Tout, Toujours)","Permission(Metz, Tous, Modifier, Tout, Toujours)","Permission(Metz, Visiteur, Administrer, Serveurs, Toujours)",
 "Elle limite l'activité, la vue et le contexte au besoin du poste."),
(2,"Quelle activité est la plus risquée à autoriser dans un contexte permanent ?","Administrer","Consulter","Imprimer","Rechercher",
 "Les actions d'administration doivent être limitées et tracées."),
(2,"Comment s'assurer qu'une règle de politique est effectivement appliquée ?","Par des tests et des journaux de décisions comparés à la politique","Par la confiance","Par l'absence de journaux","Par un mot de passe commun",
 "Mesurer l'écart entre la politique et la pratique est un contrôle essentiel."),
(2,"Que fait-on d'une règle qui n'est jamais utilisée depuis un an ?","On la réexamine et on la supprime si elle est inutile","On la garde indéfiniment","On la transforme en règle globale","On la cache",
 "Les règles obsolètes augmentent la surface d'attaque et la complexité."),
(3,"Quelle règle de priorité est la plus sûre en cas de conflit entre permission et interdiction ?","L'interdiction l'emporte","La permission l'emporte","La plus ancienne l'emporte","La plus longue l'emporte",
 "En cas de doute, on préfère refuser."),
(2,"Quel élément justifie qu'un rôle soit propre à une organisation ?","Les fonctions et responsabilités varient d'une entité à l'autre","Les rôles sont secrets","Les rôles sont éternels","Les rôles sont des mots de passe",
 "Un « gestionnaire » à Metz peut avoir des responsabilités différentes de celles d'un gestionnaire à Épinal."),
(1,"Quel est le but d'une politique de contrôle d'accès ?","Garantir que les accès restent conformes aux besoins et aux risques","Interdire tout accès","Autoriser tous les accès","Supprimer les comptes",
 "Elle équilibre sécurité et activité."),
(3,"Pourquoi sépare-t-on l'expression de la politique de sa mise en œuvre technique ?","Pour changer d'outil sans réécrire la politique","Pour supprimer les audits","Pour cacher la politique","Pour interdire la documentation",
 "La politique est un engagement stable ; la technique évolue."),
(2,"Quel document doit exister avant de configurer les droits d'un nouveau système ?","Une matrice des rôles et des accès validée par les métiers","Un fond d'écran","Un manuel de cuisine","Un plan de bâtiment",
 "Elle sert de référence et d'outil de contrôle."),
(3,"Quelle différence entre une obligation OrBAC et un contrôle a posteriori ?","L'obligation est liée à la règle au moment de l'accès, le contrôle a posteriori vérifie ensuite","Elles sont identiques","L'obligation est facultative","Le contrôle a posteriori interdit l'accès",
 "Les deux se complètent pour les accès exceptionnels."),
(2,"Quelle formulation est une règle de politique bien écrite ?","« Les gestionnaires de l'agence de Metz peuvent modifier les dossiers clients de Metz en heures ouvrées »","« Chacun fait ce qu'il faut »","« Les accès sont gérés au mieux »","« Tout est permis »",
 "Une règle précise cite qui, quoi, où et quand."),
(2,"Pourquoi faut-il une règle de gestion des exceptions ?","Les cas imprévus doivent être autorisés de façon temporaire, validée et tracée","Pour supprimer les règles","Pour augmenter les droits","Pour masquer les accès",
 "Sans procédure d'exception, les contournements se font hors contrôle."),
]
